# hierarchy
mgr={2:1,3:1,4:2,5:4,6:4,7:3,8:7,9:7,10:7,11:4,12:1}
# children map
from collections import defaultdict
ch=defaultdict(list)
for e,m in mgr.items(): ch[m].append(e)
names={1:'Alice',2:'Bob',3:'Charlie',4:'David',7:'Grace'}
def count(n):
    tot=0
    for c in ch[n]:
        tot+=1+count(c)
    return tot
for n in [1,2,3,4,7]:
    print(names[n], count(n))
